  let portRaw: string | undefined;

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i]!;
    if (arg === "-h" || arg === "--help") {
      return { kind: "help" };
    }

    const eq = arg.indexOf("=");
    const name = arg.startsWith("--") && eq !== -1 ? arg.slice(0, eq) : arg;
    let value: string | undefined;
    if (name === "--data-dir" || name === "--port") {
      if (eq !== -1 && arg.startsWith("--")) {
        value = arg.slice(eq + 1);
      } else {
        value = argv[++i];
        if (value === undefined) {
          throw new ConfigError(`${name} requires a value`);
        }
      }
    }

    switch (name) {
      case "--data-dir":
        dataDir = value;
        break;
      case "--port":
        portRaw = value;
        break;
      default:
        throw new ConfigError(`unknown argument: ${arg}`);
    }
  }

  dataDir ??= nonEmpty(env.SYNCBOX_DATA_DIR);
  portRaw ??= nonEmpty(env.SYNCBOX_PORT);

  if (dataDir === undefined || dataDir === "") {
    throw new ConfigError("--data-dir is required (or set SYNCBOX_DATA_DIR)");
  }

  const port = portRaw === undefined ? DEFAULT_PORT : parsePort(portRaw);
  return { kind: "config", config: { dataDir, port } };
}

function parsePort(raw: string): number {
  if (!/^[0-9]+$/.test(raw)) {
    throw new ConfigError(`invalid port: ${JSON.stringify(raw)} (expected an integer 1-65535)`);
  }
  const port = Number(raw);
  if (port < 1 || port > 65535) {
    throw new ConfigError(`invalid port: ${raw} (expected an integer 1-65535)`);
  }
  return port;
}

function nonEmpty(value: string | undefined): string | undefined {
  return value === undefined || value === "" ? undefined : value;
}
import { ConfigError, parseConfig, USAGE } from "./config.js";
import { startServer } from "./server.js";

const EXIT_USAGE = 2;

async function main(): Promise<number | undefined> {
  let parsed;
  try {
    parsed = parseConfig(process.argv.slice(2), process.env);
  } catch (err) {
    if (err instanceof ConfigError) {
      console.error(`syncbox-server: ${err.message}\n\n${USAGE}`);
      return EXIT_USAGE;
    }
    throw err;
  }

  if (parsed.kind === "help") {
    console.log(USAGE);
    return 0;
  }

  const { config } = parsed;
  let running;
  try {
    running = await startServer(config);
  } catch (err) {
    console.error(`syncbox-server: failed to start: ${err instanceof Error ? err.message : String(err)}`);
    return 1;
  }

  console.log(`syncbox-server listening on port ${running.port}, data dir ${config.dataDir}`);

  // Node running as PID 1 in a container gets no default signal handlers,
  // so shutdown has to be wired up explicitly.
  const shutdown = (signal: NodeJS.Signals): void => {
    console.log(`syncbox-server: received ${signal}, shutting down`);
    running.close().then(
      () => process.exit(0),
      (err: unknown) => {
        console.error("syncbox-server: error during shutdown:", err);
        process.exit(1);
      },
    );
  };
  process.once("SIGTERM", shutdown);
  process.once("SIGINT", shutdown);
  return undefined;
}

main().then(
  (code) => {
    if (code !== undefined) process.exitCode = code;
  },
  (err: unknown) => {
    console.error("syncbox-server: fatal error:", err);
    process.exit(1);
  },
);
import { constants as fsConstants } from "node:fs";
import { access, mkdir, stat } from "node:fs/promises";
import http from "node:http";
import type { AddressInfo } from "node:net";

import type { ServerConfig } from "./config.js";

export interface RunningServer {
  readonly server: http.Server;
  /** Actual port the server is bound to (useful when started with port 0). */
  readonly port: number;
  /** Stops accepting connections and waits for in-flight requests to finish. */
  close(): Promise<void>;
}

export interface StartOptions {
  /** Interface to bind; defaults to all interfaces. */
  host?: string;
  /** How long close() waits for in-flight requests before dropping them. */
  shutdownTimeoutMs?: number;
}

/**
 * Makes sure the data directory exists and is a writable directory, so that
 * misconfiguration is reported at startup rather than on the first request.
 */
export async function prepareDataDir(dataDir: string): Promise<void> {
  await mkdir(dataDir, { recursive: true });
  const info = await stat(dataDir);
  if (!info.isDirectory()) {
    throw new Error(`data dir is not a directory: ${dataDir}`);
  }
  await access(dataDir, fsConstants.R_OK | fsConstants.W_OK);
}

export function createRequestHandler(_config: ServerConfig): http.RequestListener {
  return (req, res) => {
    try {
      route(req, res);
    } catch (err) {
      console.error("unhandled error while serving request:", err);
      if (!res.headersSent) {
        sendJson(res, 500, { error: "internal server error" });
      } else {
        res.destroy();
      }
    }
  };
}

function route(req: http.IncomingMessage, res: http.ServerResponse): void {
  // Raw path without the query string. Deliberately not normalized via URL:
  // blob keys (future tickets) must be validated as sent, not after the
  // dot segments have been silently resolved.
  const path = (req.url ?? "").split("?", 1)[0];

  if (path === "/healthz") {
    if (req.method === "GET" || req.method === "HEAD") {
      sendJson(res, 200, { status: "ok" });
    } else {
      res.setHeader("Allow", "GET, HEAD");
      sendJson(res, 405, { error: "method not allowed" });
    }
    return;
  }

  sendJson(res, 404, { error: "not found" });
}

function sendJson(res: http.ServerResponse, status: number, body: unknown): void {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Content-Length": Buffer.byteLength(payload),
  });
  res.end(payload);
}

export async function startServer(config: ServerConfig, options: StartOptions = {}): Promise<RunningServer> {
  await prepareDataDir(config.dataDir);

  const server = http.createServer(createRequestHandler(config));

  // Malformed HTTP must never take the process down: answer 400 and drop
  // the connection.
  server.on("clientError", (err: NodeJS.ErrnoException, socket) => {
    if (err.code === "ECONNRESET" || !socket.writable) {
      socket.destroy();
      return;
    }
    socket.end("HTTP/1.1 400 Bad Request\r\nConnection: close\r\nContent-Length: 0\r\n\r\n");
  });

  await new Promise<void>((resolve, reject) => {
    server.once("error", reject);
    const onListening = (): void => {
      server.off("error", reject);
      resolve();
    };
    if (options.host === undefined) {
      server.listen(config.port, onListening);
    } else {
      server.listen(config.port, options.host, onListening);
    }
  });

  const shutdownTimeoutMs = options.shutdownTimeoutMs ?? 5000;
  let closing: Promise<void> | undefined;

  return {
    server,
    port: (server.address() as AddressInfo).port,
    close() {
      closing ??= new Promise<void>((resolve, reject) => {
        const timer = setTimeout(() => server.closeAllConnections(), shutdownTimeoutMs);
        timer.unref();
        server.close((err) => {
          clearTimeout(timer);
          if (err) reject(err);
          else resolve();
        });
        server.closeIdleConnections();
      });
      return closing;
    },
  };
}
#!/usr/bin/env bash
# Starts the Syncbox server in a Docker container (via docker compose) in the
# foreground of the current process.
#
#   run-server --data-dir <path> [--port <n>]
#
# Falls back to SYNCBOX_DATA_DIR / SYNCBOX_PORT; flags take precedence. The
# data dir is a host path: it is created if missing and bind-mounted into the
# container. The port is published on 127.0.0.1 (override the interface with
# SYNCBOX_PUBLISH_ADDR, e.g. 0.0.0.0).
set -euo pipefail

repo="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

usage() {
  echo "Usage: run-server --data-dir <path> [--port <n>]" >&2
}

die() {
  echo "run-server: $*" >&2
  usage
  exit 2
}

data_dir=""
port=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --data-dir) [[ $# -ge 2 ]] || die "--data-dir requires a value"; data_dir="$2"; shift 2 ;;
    --data-dir=*) data_dir="${1#*=}"; shift ;;
    --port) [[ $# -ge 2 ]] || die "--port requires a value"; port="$2"; shift 2 ;;
    --port=*) port="${1#*=}"; shift ;;
    -h|--help) usage; exit 0 ;;
    *) die "unknown argument: $1" ;;
  esac
done

data_dir="${data_dir:-${SYNCBOX_DATA_DIR:-}}"
port="${port:-${SYNCBOX_PORT:-8080}}"

[[ -n "$data_dir" ]] || die "--data-dir is required (or set SYNCBOX_DATA_DIR)"
if ! [[ "$port" =~ ^[0-9]{1,5}$ ]] || (( 10#$port < 1 || 10#$port > 65535 )); then
  die "invalid port: '$port' (expected an integer 1-65535)"
fi
port=$((10#$port))

# Create the directory as the invoking user (otherwise the Docker daemon would
# create it owned by root) and resolve it to an absolute path for the mount.
mkdir -p -- "$data_dir"
data_dir="$(cd -- "$data_dir" && pwd -P)"

export SYNCBOX_HOST_DATA_DIR="$data_dir"
export SYNCBOX_PORT="$port"
export SYNCBOX_UID="$(id -u)"
export SYNCBOX_GID="$(id -g)"
export SYNCBOX_PUBLISH_ADDR="${SYNCBOX_PUBLISH_ADDR:-127.0.0.1}"

# One compose project per port: concurrent servers on different ports don't
# touch each other's containers, and a container orphaned by a SIGKILLed
# wrapper is simply recreated by the next start on the same port.
project="$(basename "$repo" | tr '[:upper:]' '[:lower:]' | tr -c 'a-z0-9_\n-' '-')"
project="${project%$'\n'}-server-$port"
compose=(docker compose --project-directory "$repo" -f "$repo/compose.yaml" -p "$project")

# `compose up` (unlike `compose run`) stops the container gracefully on
# SIGINT/SIGTERM, but signals sent to this script have to be forwarded to it.
# --build is a no-op on a warm cache and picks up source changes otherwise.
# set -m puts compose in its own process group, so a terminal Ctrl-C or a
# signal to our whole group reaches it once (via forward) rather than twice,
# which compose would treat as "force kill".
set -m
"${compose[@]}" up --build --no-log-prefix --abort-on-container-exit --exit-code-from server server &
compose_pid=$!

stopping=0
forward() {
  stopping=1
  kill -"$1" "$compose_pid" 2>/dev/null || true
}
trap 'forward TERM' TERM
trap 'forward INT' INT
trap 'forward HUP' HUP

# `wait` returns early when a trapped signal arrives; keep waiting until
# compose itself is gone.
while :; do
  status=0
  wait "$compose_pid" || status=$?
  kill -0 "$compose_pid" 2>/dev/null || break
done
trap - TERM INT HUP

"${compose[@]}" down --timeout 10 >/dev/null 2>&1 || true

# A shutdown we were asked for is a clean exit.
if (( stopping )); then
  exit 0
fi
exit "$status"
