#   SYNCBOX_PORT           port the server listens on, both in the container
#                          and on the host (default 8080)
#   SYNCBOX_PUBLISH_ADDR   host interface the port is published on
#                          (default 127.0.0.1; set 0.0.0.0 to expose on the LAN)
#   SYNCBOX_UID/GID        user the server runs as, so files in the data dir
#                          are owned by the invoking host user (default 1000)

services:
  server:
    # Fixed tag: run-server uses a separate compose project per port, and
    # they should all share one image rather than each building its own.
    image: syncbox-server:local
    build:
      context: .
      target: server
    init: true
    # Docker's default bridge: no per-project network has to be created, so
    # several servers (on different ports) can be started concurrently.
